import {icon} from "./icons.js";
import {escapeHtml as esc} from "../account.js";
import {parseDate, WEEKDAYS} from "../date.js";
import {recurrenceLabel} from "../recurrence.js";

function recurrenceFields(draft) {
  const rule = draft.recurrence;
  const frequency = rule?.frequency || "none";
  const ending = rule?.until ? "until" : rule?.count ? "count" : "never";
  const weekdays = rule?.weekdays || [parseDate(draft.date).getUTCDay()];
  return `<div class="event-recurrence"><div class="event-field"><label class="field-label" for="event-frequency">Répétition</label><select id="event-frequency" name="recurrenceFrequency" aria-controls="event-recurrence-options">${[["none", "Ne se répète pas"], ["daily", "Chaque jour"], ["weekly", "Chaque semaine"], ["monthly", "Chaque mois"], ["yearly", "Chaque année"]].map(([value, label]) => `<option value="${value}" ${frequency === value ? "selected" : ""}>${label}</option>`).join("")}</select></div>
    <div id="event-recurrence-options" ${rule ? "" : "hidden"}>
      <div class="recurrence-interval"><label class="field-label" id="event-interval-prefix" for="event-interval">${frequency === "weekly" ? "Toutes les" : "Tous les"}</label><input id="event-interval" type="number" name="recurrenceInterval" min="1" max="99" step="1" value="${rule?.interval || 1}" ${rule ? "required" : "disabled"}/><span id="event-interval-unit">${({daily: "jours", weekly: "semaines", monthly: "mois", yearly: "ans"})[frequency] || "semaines"}</span></div>
      <fieldset id="event-weekdays" class="recurrence-weekdays" ${frequency === "weekly" ? "" : "hidden"}><legend class="field-label">Les jours suivants</legend><div>${[1, 2, 3, 4, 5, 6, 0].map(day => `<label title="${WEEKDAYS[day]}"><input type="checkbox" name="recurrenceWeekdays" value="${day}" aria-label="${WEEKDAYS[day]}" ${weekdays.includes(day) ? "checked" : ""} ${frequency === "weekly" ? "" : "disabled"}/><span>${WEEKDAYS[day].slice(0, 3)}</span></label>`).join("")}</div></fieldset>
      <div class="event-datetime recurrence-ending"><div class="event-field"><label class="field-label" for="event-recurrence-end">Fin de la répétition</label><select id="event-recurrence-end" name="recurrenceEnd" ${rule ? "" : "disabled"}>${[["never", "Jamais"], ["until", "À une date"], ["count", "Après un nombre d’occurrences"]].map(([value, label]) => `<option value="${value}" ${ending === value ? "selected" : ""}>${label}</option>`).join("")}</select></div>
      <div class="event-field" id="event-until-field" ${ending === "until" ? "" : "hidden"}><label class="field-label" for="event-until">Dernière date incluse</label><input id="event-until" type="date" name="recurrenceUntil" min="${esc(draft.date)}" max="9999-12-31" value="${rule?.until || draft.date}" ${rule && ending === "until" ? "required" : "disabled"}/></div>
      <div class="event-field" id="event-count-field" ${ending === "count" ? "" : "hidden"}><label class="field-label" for="event-count">Nombre d’occurrences</label><input id="event-count" type="number" name="recurrenceCount" min="1" max="1000" step="1" value="${rule?.count || 10}" ${rule && ending === "count" ? "required" : "disabled"}/></div></div>
      <p id="event-recurrence-summary" class="recurrence-summary" aria-live="polite">${esc(recurrenceLabel(rule))}</p><p id="event-recurrence-date-note" class="recurrence-summary" hidden></p>
    </div></div>`;
}

export function eventDialog({event, date, aiAvailable}) {
  const editing = !!event;
  const draft = event || {title: "", description: "", date, endDate: date, startTime: "09:00", endTime: "10:00", allDay: false};
  return `<dialog class="app-dialog event-dialog" aria-labelledby="event-dialog-title" aria-describedby="event-dialog-description">
    <header class="dialog-heading"><div><span class="event-dialog-eyebrow">${editing ? "TON CALENDRIER" : "UN MOMENT À PRÉVOIR"}</span><h2 id="event-dialog-title">${editing ? "Modifier l’événement" : "Nouvel événement"}</h2></div><button class="icon-button" data-action="close-event-dialog" aria-label="Fermer la fenêtre">${icon("close")}</button></header>
    <p class="dialog-description" id="event-dialog-description">${editing ? event.recurrence ? "Tu modifies toute la série. Les dates ci-dessous sont celles de la première occurrence." : "Ajuste les détails, puis enregistre tes changements." : "Une idée, un rendez-vous, un moment pour toi. Ajoute-le à ton calendrier."}</p>
    ${editing ? "" : `<div class="event-tabs" role="tablist" aria-label="Mode de création"><button id="natural-tab" role="tab" aria-controls="natural-panel" aria-selected="${aiAvailable}" tabindex="${aiAvailable ? 0 : -1}" data-action="event-natural">${icon("sparkles")}En quelques mots</button><button id="manual-tab" role="tab" aria-controls="manual-panel" aria-selected="${!aiAvailable}" tabindex="${aiAvailable ? -1 : 0}" data-action="event-manual">${icon("edit")}Saisir les détails</button></div>
    <section id="natural-panel" role="tabpanel" aria-labelledby="natural-tab" ${aiAvailable ? "" : "hidden"}><form id="event-interpret-form"><label class="field-label" for="event-prompt">Qu’est-ce que tu veux prévoir?</label><textarea id="event-prompt" name="text" rows="4" maxlength="2000" placeholder="Ex. : Souper avec Camille vendredi à 19 h, pendant deux heures, au restaurant du quartier." required></textarea><div class="prompt-examples"><span>Essaie aussi</span><button type="button" data-action="event-example" data-text="Dentiste demain à 14 h pendant 45 minutes">Dentiste demain à 14 h</button><button type="button" data-action="event-example" data-text="Congé vendredi, toute la journée">Congé vendredi</button></div><div class="dialog-actions"><button type="button" class="secondary-button" data-action="close-event-dialog">Annuler</button><button type="submit" class="primary-button">Préparer l’événement ${icon("arrowRight")}</button></div></form></section>`}
    <section id="manual-panel" ${editing ? "" : 'role="tabpanel" aria-labelledby="manual-tab"'} ${!editing && aiAvailable ? "hidden" : ""}>
      ${!editing ? `<div id="event-review" class="event-review" role="status" hidden>${icon("check")}<span>Les détails sont prêts. Vérifie-les avant d’ajouter l’événement.</span></div>${!aiAvailable ? '<p class="ai-offline-note">La création assistée est indisponible. Tu peux ajouter ton événement ici.</p>' : ""}` : ""}
      <form id="event-save-form"><div class="event-fields"><div class="event-field"><label class="field-label" for="event-title">Titre <span aria-hidden="true">*</span></label><input id="event-title" name="title" type="text" value="${esc(draft.title)}" placeholder="Donne un nom à ce moment" maxlength="160" required/></div>
      <label class="all-day-toggle"><input type="checkbox" name="allDay" ${draft.allDay ? "checked" : ""}/><span>Toute la journée</span></label>
      <div class="event-datetime"><div class="event-field"><label class="field-label" for="event-date">Date de début</label><input id="event-date" type="date" name="date" value="${esc(draft.date)}" min="0001-01-01" max="9999-12-31" required/></div><div class="event-field event-time-field" ${draft.allDay ? "hidden" : ""}><label class="field-label" for="event-start">Heure de début</label><input id="event-start" type="time" name="startTime" value="${draft.startTime || "09:00"}" ${draft.allDay ? "disabled" : "required"}/></div></div>
      <div class="event-datetime"><div class="event-field"><label class="field-label" for="event-end-date">Date de fin</label><input id="event-end-date" type="date" name="endDate" value="${esc(draft.endDate)}" min="${esc(draft.date)}" max="9999-12-31" required/></div><div class="event-field event-time-field" ${draft.allDay ? "hidden" : ""}><label class="field-label" for="event-end">Heure de fin</label><input id="event-end" type="time" name="endTime" value="${draft.endTime || "10:00"}" ${draft.allDay ? "disabled" : "required"}/></div></div>
      <p class="event-zone">${icon("globe")}Heure de Toronto <span>·</span> America/Toronto</p>${recurrenceFields(draft)}<div class="event-field"><label class="field-label" for="event-description">Description <span class="optional-label">facultative</span></label><textarea id="event-description" name="description" rows="3" maxlength="4000" placeholder="Un lieu, une note, quelque chose à ne pas oublier…">${esc(draft.description)}</textarea></div></div>
      <div class="dialog-actions event-save-actions">${editing ? `<button type="button" class="danger-link" data-action="event-delete">${icon("trash")}Supprimer</button>` : ""}<button type="button" class="secondary-button" data-action="close-event-dialog">Annuler</button><button type="submit" class="primary-button">${editing ? "Enregistrer" : "Ajouter au calendrier"} ${icon("check")}</button></div></form>
    </section><p id="event-error" class="event-error" role="alert" tabindex="-1" hidden></p>
    <section id="event-delete-confirm" class="event-confirm" aria-label="Confirmer la suppression" hidden><strong>${event?.recurrence ? "Supprimer toute la série?" : "Supprimer cet événement?"}</strong><p>${event?.recurrence ? "Toutes les occurrences seront retirées de ton calendrier." : "Il sera retiré de ton calendrier."} Cette action est définitive.</p><div><button class="secondary-button" data-action="event-delete-cancel">${event?.recurrence ? "Garder la série" : "Garder l’événement"}</button><button class="danger-button" data-action="event-delete-confirm">${event?.recurrence ? "Supprimer la série" : "Supprimer l’événement"}</button></div></section>
    <section id="event-discard-confirm" class="event-confirm" aria-label="Modifications non enregistrées" hidden><strong>Quitter sans enregistrer?</strong><p>Les détails saisis dans cette fenêtre seront perdus.</p><div><button class="secondary-button" data-action="event-discard-cancel">Continuer</button><button class="danger-button" data-action="event-discard-confirm">Quitter</button></div></section>
  </dialog>`;
}
